final startIndex = int.tryParse(params['startIndex'] ?? '0') ?? 0;

// Use the same filename/tag parsing as the library scan so the hero
// (Dot/Spectrum/Void) can render both artist + title.
final extractor = createMetadataExtractor();
final tracks = <AudioTrack>[];
for (final raw in pathsCsv.split(',')) {
  final trimmed = raw.trim();
  if (trimmed.isEmpty) continue;
  try {
    tracks.add(await extractor.extractMetadata(trimmed));
  } catch (_) {
    tracks.add(
      AudioTrack(path: trimmed, title: trimmed.split('/').last),
    );
  }
}

await p.setQueue(tracks, startIndex: startIndex);
return _ok({'queued': tracks.length, 'startIndex': startIndex});

